const escapeHtml = (value) =>
  String(value).replace(/[&<>"']/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;",
  })[character]);

const nav = document.querySelector("#main-nav");
const layout = document.querySelector("#menu-layout");

function renderSection(section) {
  const items = section.items.map((item) => `
    <li class="menu-item">
      <div class="item-line">
        <span class="item-name">${escapeHtml(item.name)}</span>
        <span class="item-dots" aria-hidden="true"></span>
        <span class="item-price">${escapeHtml(item.price)}</span>
      </div>
      ${item.note ? `<p class="item-note">${escapeHtml(item.note)}</p>` : ""}
    </li>`).join("");

  return `
    <section class="menu-category" id="${escapeHtml(section.id)}">
      <h3>${escapeHtml(section.title)}</h3>
      <ul class="menu-list">${items}</ul>
    </section>`;
}

const firstColumn = menu.slice(0, 2).map(renderSection).join("");
const secondColumn = menu.slice(2, 4).map(renderSection).join("");
const lastColumns = menu.slice(4).map((section) => `
  <div class="menu-column">${renderSection(section)}</div>`).join("");

layout.innerHTML = `
  <div class="menu-column">
    ${firstColumn}
    <img class="menu-photo" src="data:image/jpeg;base64," alt="Croissant salé et quiche" loading="lazy" />
  </div>
  <div class="menu-column">
    ${secondColumn}
    <img class="menu-photo" src="data:image/jpeg;base64," alt="Espresso et cappuccino sur marbre" loading="lazy" />
  </div>
  ${lastColumns}`;

const menuPhotos = [...layout.querySelectorAll(".menu-photo")];

function renderPublicMenu() {
  const columns = [[], []];
  menu.forEach((section, index) => columns[index % 2].push(renderSection(section)));

  nav.innerHTML = [
    ...menu.map((section) => `<a href="#${escapeHtml(section.id)}">${escapeHtml(section.title)}</a>`),
    '<a href="#infos">Infos</a>',
  ].join("");

  layout.innerHTML = columns.map((sections, index) => `
    <div class="menu-column">
      ${sections.join("")}
      ${menuPhotos[index] ? menuPhotos[index].outerHTML : ""}
    </div>`).join("");

  const mobileCafePhoto = menuPhotos[1].cloneNode();
  mobileCafePhoto.classList.add("menu-photo-mobile");
  layout.querySelector("#glaces").after(mobileCafePhoto);

  const mobileSavoryPhoto = menuPhotos[0].cloneNode();
  mobileSavoryPhoto.classList.add("menu-photo-mobile");
  layout.querySelector("#sales").after(mobileSavoryPhoto);
}

renderPublicMenu();
